import { validateDateRange } from "@mui/x-date-pickers-pro/validation";
import { useValidation } from "@mui/x-date-pickers-pro";
import { STATE } from "../stateMachine/dateRangePickerState";
import { validateTimeFrame } from "../util/validateTimeFrame";
import dayjs from "dayjs";
export const useValidateValue = ({ clearable, currentCustomValue, currentTimeFrameValue, flattenedPresets, ianaTimezone, isDirty, maxCustomRange, minCustomRange, maxDate, minDate, now, onParse, state, units, }) => {
    const { hasValidationError, validationError } = useValidation({
        props: {
            disableFuture: false,
            disablePast: false,
            maxDate,
            minDate,
        },
        timezone: ianaTimezone,
        validator: validateDateRange,
        value: currentCustomValue,
    });
    if (!isDirty) {
        return undefined;
    }
    if (state === STATE.CUSTOM) {
        if (!(currentCustomValue[0] && currentCustomValue[1])) {
            return clearable ? undefined : "Date range is invalid";
        }
        if (currentCustomValue[0].isSame(currentCustomValue[1])) {
            return "Date range is invalid";
        }
        const selectedDuration = dayjs.duration(currentCustomValue[1].diff(currentCustomValue[0]));
        const maxRange = maxCustomRange
            ? dayjs.duration(maxCustomRange.number, maxCustomRange.unit)
            : undefined;
        if (maxCustomRange &&
            selectedDuration.asSeconds() > maxRange.asSeconds()) {
            return `Date range must be less than ${maxCustomRange.number} ${maxCustomRange.unit}${maxCustomRange.number > 1 ? "s" : ""}`;
        }
        const minRange = minCustomRange
            ? dayjs.duration(minCustomRange.number, minCustomRange.unit)
            : undefined;
        if (minCustomRange &&
            selectedDuration.asSeconds() < minRange.asSeconds()) {
            return `Date range must be greater than ${minCustomRange.number} ${minCustomRange.unit}${minCustomRange.number > 1 ? "s" : ""}`;
        }
        if (!hasValidationError) {
            return undefined;
        }
        // based off the mui validation error types
        // https://github.dev/mui/mui-x/blob/master/packages/x-date-pickers-pro/src/managers/useDateRangeManager.ts
        switch (validationError[1]) {
            case "maxDate":
                return "End date is invalid";
            case "minDate":
            case "disablePast":
                return "Start date is invalid";
            case "invalidDate":
            default:
                return "Date range is invalid";
        }
    }
    return validateTimeFrame({
        clearable,
        flattenedPresets,
        maxCustomRange,
        minCustomRange,
        now,
        onParse,
        units,
        value: currentTimeFrameValue,
    });
};
